import { I18N_BASE_URL, LANGUAGE_STORAGE_KEY } from "./config.js";
import { emit, setState } from "./state.js";

// ============================================================
// I18N — every user-visible string lives in static/i18n/<lang>.json
//
// Flat key → string dictionaries (e.g. "projection.mercator.name"), English
// being the source of truth. init() awaits setLanguage() before the first
// render, so every t() call already has its strings.
// Country names are in static/i18n/countries/<lang>.json, generated by
// scripts/fetch_geodata.py and keyed by the English name the map data uses.
// ============================================================
const SOURCE_LANGUAGE = "en";

// Each language is listed under its own name, the only one its readers can
// be counted on to recognise: that is why these are not translated strings.
export const LANGUAGES = [
  { code: "en", name: "English" },
  { code: "fr", name: "Français" },
];

let messages = {};
let countryNames = {};

const fetchJson = (path) => fetch(`${I18N_BASE_URL}${path}.json`).then((response) => response.json());

// The English name is the fallback, and what the map data calls the country.
export function countryName(name) {
  return countryNames[name] ?? name;
}

// A language chosen earlier wins; otherwise the first of the browser's
// languages we have, so that most people never need to look for the picker.
export function preferredLanguage() {
  const saved = localStorage.getItem(LANGUAGE_STORAGE_KEY);
  const codes = LANGUAGES.map((language) => language.code);
  if (codes.includes(saved)) return saved;
  const browser = navigator.languages.map((tag) => tag.split("-")[0].toLowerCase());
  return browser.find((code) => codes.includes(code)) ?? SOURCE_LANGUAGE;
}

// A missing key returns the key itself (visible in the UI, so it gets
// noticed) and warns once in the console rather than crashing the render.
export function t(key, vars = {}) {
  const template = messages[key];
  if (template === undefined) {
    console.warn(`[i18n] missing key: ${key}`);
    return key;
  }
  return template.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? `{${name}}`);
}

// Static markup opts in with attributes instead of being rebuilt in JS:
//   data-i18n="key"                     → textContent
//   data-i18n-html="key"                → innerHTML (our own trusted files only,
//                                         for the few strings with inline <strong>)
//   data-i18n-attr="aria-label:key;…"   → any attribute
function applyStaticTranslations() {
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });
  document.querySelectorAll("[data-i18n-html]").forEach((el) => {
    el.innerHTML = t(el.dataset.i18nHtml);
  });
  document.querySelectorAll("[data-i18n-attr]").forEach((el) => {
    el.dataset.i18nAttr.split(";").forEach((pair) => {
      const [attr, key] = pair.split(":");
      el.setAttribute(attr, t(key));
    });
  });
  document.title = t("app.title");
}

// Loads a language and re-renders every text: the static markup here, the
// built UI through its "language:changed" subscribers. Also how the app
// starts (init), so the first build and a later switch take the same path.
export async function setLanguage(lang) {
  const translated = lang !== SOURCE_LANGUAGE;
  const [source, translation, countries] = await Promise.all([
    fetchJson(SOURCE_LANGUAGE),
    translated ? fetchJson(lang) : {},
    translated ? fetchJson(`countries/${lang}`) : {},
  ]);
  // A key the translation lacks shows in English rather than as a raw key.
  messages = { ...source, ...translation };
  countryNames = countries;
  document.documentElement.lang = lang;
  applyStaticTranslations();
  setState({ language: lang });
  emit("language:changed");
}
